        ["Custom policy: the policy hash must be hexadecimal (the digest of the policy document)."] = ("Política customizada: o hash da política deve ser hexadecimal (o resumo do documento da política).", "Política personalizada: el hash de la política debe ser hexadecimal (el resumen del documento de la política)."),
        ["Only SignWithDetailsAsync (Sign now) reports a lower achieved level; deferred and batch always throw."] = ("Só o SignWithDetailsAsync (Assinar agora) informa um nível menor alcançado; adiado e lote sempre lançam exceção.", "Solo SignWithDetailsAsync (Firmar ahora) informa un nivel menor alcanzado; diferido y lote siempre lanzan excepción."),
        ["The sandbox is offline. Switch to Real to use public TSAs."] = ("O sandbox é offline. Mude para Real para usar TSAs públicas.", "El sandbox no tiene conexión. Cambie a Real para usar TSA públicas."),
        ["Sandbox services exist only in Sandbox mode."] = ("Os serviços do sandbox só existem no modo Sandbox.", "Los servicios del sandbox solo existen en modo Sandbox."),
        ["The sandbox TSA does not check TLS client certificates; the option is still passed to TimestampOptions.ClientCertificate."] = ("A TSA do sandbox não verifica certificados de cliente TLS; a opção ainda é passada para TimestampOptions.ClientCertificate.", "La TSA del sandbox no verifica certificados de cliente TLS; la opción igual se pasa a TimestampOptions.ClientCertificate."),
        ["Signature TSA"] = ("TSA da assinatura", "TSA de la firma"),
        ["Archive TSA"] = ("TSA de arquivamento", "TSA de archivo"),
        ["AD-RA in the sandbox embeds simulated policy artifacts (PA, LPA and LPA signature); in Real mode they are downloaded from the ITI and the LPA signature is checked."] = ("No sandbox, o AD-RA embute artefatos de política simulados (PA, LPA e assinatura da LPA); no modo Real eles são baixados do ITI e a assinatura da LPA é verificada.", "En el sandbox, AD-RA incrusta artefactos de política simulados (PA, LPA y firma de la LPA); en modo Real se descargan del ITI y se verifica la firma de la LPA."),
