        ["SHA-3 is not available in this runtime (needs OpenSSL 1.1.1+ or Windows 11)."] = ("SHA-3 não está disponível neste runtime (requer OpenSSL 1.1.1+ ou Windows 11).", "SHA-3 no está disponible en este runtime (requiere OpenSSL 1.1.1+ o Windows 11)."),
