        ["RSASSA-PSS cannot be combined with a SHA-3 digest: choose SHA-2 or PKCS#1 v1.5."] = ("RSASSA-PSS não combina com digest SHA-3: escolha SHA-2 ou PKCS#1 v1.5.", "RSASSA-PSS no se puede combinar con un digest SHA-3: elija SHA-2 o PKCS#1 v1.5."),
        ["ICP-Brasil PAdES policies mandate /Filter /PBAD_PAdES /SubFilter /PBAD.PAdES (DOC-ICP-15.03)."] = ("As políticas PAdES ICP-Brasil exigem /Filter /PBAD_PAdES /SubFilter /PBAD.PAdES (DOC-ICP-15.03).", "Las políticas PAdES ICP-Brasil exigen /Filter /PBAD_PAdES /SubFilter /PBAD.PAdES (DOC-ICP-15.03)."),
        ["Fixed by the ICP-Brasil policy."] = ("Definido pela política ICP-Brasil.", "Fijado por la política ICP-Brasil."),
        ["PDF/A-1 (ISO 19005-1) only allows adbe.pkcs7.detached signatures."] = ("PDF/A-1 (ISO 19005-1) só permite assinaturas adbe.pkcs7.detached.", "PDF/A-1 (ISO 19005-1) solo permite firmas adbe.pkcs7.detached."),
        ["Legacy PKCS#7: only for B-B. B-T and above need ETSI.CAdES.detached."] = ("PKCS#7 legado: só para B-B. B-T e acima precisam de ETSI.CAdES.detached.", "PKCS#7 heredado: solo para B-B. B-T y superiores necesitan ETSI.CAdES.detached."),
        ["Set automatically by the ICP-Brasil policies (choose ICP-Brasil in Signature type)."] = ("Definido automaticamente pelas políticas ICP-Brasil (escolha ICP-Brasil em Tipo de assinatura).", "Se define automáticamente con las políticas ICP-Brasil (elija ICP-Brasil en Tipo de firma)."),
        ["The document is not PDF/A."] = ("O documento não é PDF/A.", "El documento no es PDF/A."),
        ["WithPdfAPreservation is a PadesSignerBuilder option (Sign now only)."] = ("WithPdfAPreservation é uma opção do PadesSignerBuilder (só em Assinar agora).", "WithPdfAPreservation es una opción de PadesSignerBuilder (solo en Firmar ahora)."),
        ["This is a PDF/A document: turn on PDF/A preservation to have the library refuse options that would break conformance."] = ("Este é um documento PDF/A: ligue a preservação PDF/A para a biblioteca recusar opções que quebrariam a conformidade.", "Este es un documento PDF/A: active la preservación PDF/A para que la biblioteca rechace opciones que romperían la conformidad."),
        ["Reserved /Contents size must be between 4096 and 200000 bytes."] = ("O tamanho reservado de /Contents deve ficar entre 4096 e 200000 bytes.", "El tamaño reservado de /Contents debe estar entre 4096 y 200000 bytes."),
        ["The document has no empty signature field."] = ("O documento não tem campo de assinatura vazio.", "El documento no tiene un campo de firma vacío."),
        ["The document has no empty signature field: choose New field."] = ("O documento não tem campo de assinatura vazio: escolha Novo campo.", "El documento no tiene un campo de firma vacío: elija Campo nuevo."),
        ["Choose which empty field to sign."] = ("Escolha qual campo vazio assinar.", "Elija qué campo vacío firmar."),
        ["The field name is required and cannot contain '.' (it separates names in a field hierarchy)."] = ("O nome do campo é obrigatório e não pode conter '.' (ele separa nomes numa hierarquia de campos).", "El nombre del campo es obligatorio y no puede contener '.' (separa nombres en una jerarquía de campos)."),
        ["The document already has a signature field named '{0}'."] = ("O documento já tem um campo de assinatura chamado '{0}'.", "El documento ya tiene un campo de firma llamado '{0}'."),
        ["The stamp is drawn in the existing field's rectangle."] = ("O carimbo é desenhado no retângulo do campo existente.", "El sello se dibuja en el rectángulo del campo existente."),
        ["The stamp needs a positive width and height."] = ("O carimbo precisa de largura e altura positivas.", "El sello necesita un ancho y un alto positivos."),
        ["DeferredSigner only takes SignatureFieldOptions (reason, location, contact, signer name)."] = ("O DeferredSigner só aceita SignatureFieldOptions (motivo, local, contato, nome do signatário).", "DeferredSigner solo acepta SignatureFieldOptions (motivo, ubicación, contacto, nombre del firmante)."),
        ["BatchSigner only takes SignatureFieldOptions (reason, location, contact, signer name)."] = ("O BatchSigner só aceita SignatureFieldOptions (motivo, local, contato, nome do signatário).", "BatchSigner solo acepta SignatureFieldOptions (motivo, ubicación, contacto, nombre del firmante)."),
        ["AEA (Lei 14.063) is the non-ICP route: an ICP-Brasil signature is already a qualified signature (QES) and carries its own policy."] = ("A AEA (Lei 14.063) é o caminho fora da ICP: uma assinatura ICP-Brasil já é qualificada e traz a própria política.", "La AEA (Lei 14.063) es la vía fuera de ICP: una firma ICP-Brasil ya es cualificada y lleva su propia política."),
        ["AEA writes its own signature-policy-identifier; it cannot be combined with a custom policy."] = ("A AEA grava o próprio signature-policy-identifier; não combina com uma política customizada.", "La AEA escribe su propio signature-policy-identifier; no se puede combinar con una política personalizada."),
        ["The signature policy comes from the Signature type step."] = ("A política de assinatura vem do passo Tipo de assinatura.", "La política de firma viene del paso Tipo de firma."),
        ["AEA: the signer name is required."] = ("AEA: o nome do signatário é obrigatório.", "AEA: el nombre del firmante es obligatorio."),
        ["AEA: enter a valid CPF (11 digits with check digits)."] = ("AEA: informe um CPF válido (11 dígitos com dígitos verificadores).", "AEA: ingrese un CPF válido (11 dígitos con dígitos verificadores)."),
        ["Signer metadata: the signer name is required."] = ("Metadados do signatário: o nome é obrigatório.", "Metadatos del firmante: el nombre es obligatorio."),
        ["The document information dictionary cannot be changed when signing an existing field."] = ("O dicionário de informações do documento não pode ser alterado ao assinar um campo existente.", "El diccionario de información del documento no se puede cambiar al firmar un campo existente."),
        ["Health-document metadata is written to the document information dictionary, which cannot be changed when signing an existing field."] = ("Os metadados de documento de saúde vão para o dicionário de informações do documento, que não pode ser alterado ao assinar um campo existente.", "Los metadatos de documento de salud se escriben en el diccionario de información del documento, que no se puede cambiar al firmar un campo existente."),
        ["Health document: add at least one professional registration."] = ("Documento de saúde: adicione ao menos um registro profissional.", "Documento de salud: agregue al menos un registro profesional."),
        ["Document info key '{0}' must be printable ASCII without PDF delimiters."] = ("A chave '{0}' das informações do documento deve ser ASCII imprimível sem delimitadores de PDF.", "La clave '{0}' de la información del documento debe ser ASCII imprimible sin delimitadores de PDF."),
        ["Only the first signature of a document can certify it (ISO 32000-1 §12.8.2.2); this document is already signed."] = ("Só a primeira assinatura de um documento pode certificá-lo (ISO 32000-1 §12.8.2.2); este documento já está assinado.", "Solo la primera firma de un documento puede certificarlo (ISO 32000-1 §12.8.2.2); este documento ya está firmado."),
        ["The document is already signed: certification is no longer possible."] = ("O documento já está assinado: certificar não é mais possível.", "El documento ya está firmado: ya no es posible certificar."),
        ["Choose a signer (certificate)."] = ("Escolha um signatário (certificado).", "Elija un firmante (certificado)."),
        ["The certificate has expired: the library refuses to sign with it (SigningException)."] = ("O certificado expirou: a biblioteca se recusa a assinar com ele (SigningException).", "El certificado venció: la biblioteca se niega a firmar con él (SigningException)."),
        ["The certificate is not valid yet: the library refuses to sign with it (SigningException)."] = ("O certificado ainda não é válido: a biblioteca se recusa a assinar com ele (SigningException).", "El certificado aún no es válido: la biblioteca se niega a firmar con él (SigningException)."),
        ["The certificate lacks the nonRepudiation key usage: ICP-Brasil validators warn about it."] = ("O certificado não tem o uso de chave nonRepudiation: validadores ICP-Brasil avisam.", "Al certificado le falta el uso de clave nonRepudiation: los validadores ICP-Brasil lo advierten."),
        ["The certificate does not chain to an ICP-Brasil root: the signature will carry the policy, but it will not be valid under it."] = ("O certificado não encadeia numa raiz ICP-Brasil: a assinatura levará a política, mas não será válida sob ela.", "El certificado no encadena con una raíz ICP-Brasil: la firma llevará la política, pero no será válida bajo ella."),
        ["{0}: enter an absolute http://, https:// or tcp:// URL."] = ("{0}: informe uma URL absoluta http://, https:// ou tcp://.", "{0}: ingrese una URL absoluta http://, https:// o tcp://."),
        ["{0}: the sandbox is offline; only *.{1} URLs answer."] = ("{0}: o sandbox é offline; só URLs *.{1} respondem.", "{0}: el sandbox no tiene conexión; solo responden URLs *.{1}."),
        ["{0}: Basic authentication needs a user and a password."] = ("{0}: autenticação Basic precisa de usuário e senha.", "{0}: la autenticación Basic necesita usuario y contraseña."),
        ["{0}: Bearer authentication needs a token."] = ("{0}: autenticação Bearer precisa de um token.", "{0}: la autenticación Bearer necesita un token."),
        ["{0}: the authenticated sandbox TSA needs Basic authentication ({1} / {2})."] = ("{0}: a TSA autenticada do sandbox precisa de autenticação Basic ({1} / {2}).", "{0}: la TSA autenticada del sandbox necesita autenticación Basic ({1} / {2})."),

        // ── Catalog ────────────────────────────────────────────────────
        ["Sandbox"] = ("Sandbox", "Sandbox"),
        ["Everything runs offline against simulated services."] = ("Tudo roda offline contra serviços simulados.", "Todo funciona sin conexión contra servicios simulados."),
        ["A test PKI (AC Raiz Sandbox SimpleSign), an RFC 3161 TSA, CRLs, a fake ICP-Brasil PSC and a fake CSC v2 service, all answered in-process on *.sandbox.simplesign.test. Signatures validate here, but no real validator trusts the sandbox root."] = ("Uma PKI de teste (AC Raiz Sandbox SimpleSign), uma TSA RFC 3161, LCRs, um PSC ICP-Brasil e um serviço CSC v2 simulados, todos respondidos no próprio processo em *.sandbox.simplesign.test. As assinaturas validam aqui, mas nenhum validador real confia na raiz do sandbox.", "Una PKI de prueba (AC Raiz Sandbox SimpleSign), una TSA RFC 3161, CRLs, un PSC ICP-Brasil y un servicio CSC v2 simulados, todos respondidos en el propio proceso en *.sandbox.simplesign.test. Las firmas se validan aquí, pero ningún validador real confía en la raíz del sandbox."),
        ["Real"] = ("Real", "Real"),
        ["Your certificates, real TSAs and real cloud providers."] = ("Seus certificados, TSAs reais e provedores de nuvem reais.", "Sus certificados, TSA reales y proveedores en la nube reales."),
        ["Use a PFX, the OS certificate store, an A3 token or a real PSC/CSC account. TSAs, CRLs and OCSP are reached over the internet. Validation trusts the OS roots and the ICP-Brasil roots bundled with SimpleSign.Brasil."] = ("Use um PFX, o repositório do sistema, um token A3 ou uma conta real de PSC/CSC. TSAs, LCRs e OCSP são acessados pela internet. A validação confia nas raízes do sistema e nas raízes ICP-Brasil incluídas no SimpleSign.Brasil.", "Use un PFX, el almacén del sistema, un token A3 o una cuenta real de PSC/CSC. Las TSA, CRL y OCSP se consultan por internet. La validación confía en las raíces del sistema y en las raíces ICP-Brasil incluidas en SimpleSign.Brasil."),
        ["Document"] = ("Documento", "Documento"),
        ["The PDF to sign. Its facts decide what the next steps offer."] = ("O PDF a assinar. As características dele decidem o que os próximos passos oferecem.", "El PDF a firmar. Sus características deciden lo que ofrecen los pasos siguientes."),
        ["SimpleSign signs with an incremental update: the original bytes are kept and a new revision is appended, so existing signatures stay valid."] = ("O SimpleSign assina com atualização incremental: os bytes originais são mantidos e uma nova revisão é anexada, então as assinaturas existentes continuam válidas.", "SimpleSign firma con actualización incremental: se conservan los bytes originales y se agrega una nueva revisión, así que las firmas existentes siguen siendo válidas."),
        ["DocMDP (certification)"] = ("DocMDP (certificação)", "DocMDP (certificación)"),
        ["A certified document says which later changes are allowed."] = ("Um documento certificado diz quais alterações posteriores são permitidas.", "Un documento certificado indica qué cambios posteriores se permiten."),
        ["P=1: no changes, so no further signature. P=2: form filling and signing. P=3: also annotations."] = ("P=1: nenhuma alteração, nem nova assinatura. P=2: preenchimento de formulário e assinaturas. P=3: também anotações.", "P=1: ningún cambio, ni nuevas firmas. P=2: rellenado de formularios y firmas. P=3: también anotaciones."),
        ["Sandbox certificate"] = ("Certificado do sandbox", "Certificado del sandbox"),
        ["A1 certificates from the sandbox PKI: every key type and the edge cases."] = ("Certificados A1 da PKI do sandbox: todos os tipos de chave e os casos-limite.", "Certificados A1 de la PKI del sandbox: todos los tipos de clave y los casos límite."),
        ["Each one carries ICP-Brasil-style data (CPF in the SAN otherName 2.16.76.1.3.1, or CNPJ in 2.16.76.1.3.3) and CRL distribution points served by the sandbox."] = ("Cada um traz dados no estilo ICP-Brasil (CPF no otherName do SAN 2.16.76.1.3.1, ou CNPJ em 2.16.76.1.3.3) e pontos de distribuição de LCR servidos pelo sandbox.", "Cada uno lleva datos al estilo ICP-Brasil (CPF en el otherName del SAN 2.16.76.1.3.1, o CNPJ en 2.16.76.1.3.3) y puntos de distribución de CRL servidos por el sandbox."),
        ["A1 (PFX file)"] = ("A1 (arquivo PFX)", "A1 (archivo PFX)"),
        ["A certificate and private key in a PKCS#12 file."] = ("Um certificado e a chave privada em um arquivo PKCS#12.", "Un certificado y su clave privada en un archivo PKCS#12."),
        ["The password opens the file once; it is not stored. Intermediate certificates in the file are embedded in the signature."] = ("A senha abre o arquivo uma vez e não é guardada. Os certificados intermediários do arquivo vão embutidos na assinatura.", "La contraseña abre el archivo una vez y no se guarda. Los certificados intermedios del archivo se incrustan en la firma."),
        ["OS certificate store"] = ("Repositório do sistema", "Almacén del sistema"),
        ["Certificates with a private key in the Windows store or the macOS keychain."] = ("Certificados com chave privada no repositório do Windows ou nas Chaves do macOS.", "Certificados con clave privada en el almacén de Windows o en el llavero de macOS."),
        ["The OS may prompt for the keychain password or the smartcard PIN when the key is used."] = ("O sistema pode pedir a senha das Chaves ou o PIN do cartão quando a chave for usada.", "El sistema puede pedir la contraseña del llavero o el PIN de la tarjeta cuando se use la clave."),
        ["A3 token (PKCS#11)"] = ("Token A3 (PKCS#11)", "Token A3 (PKCS#11)"),
        ["Smartcards and USB tokens through their PKCS#11 driver."] = ("Cartões e tokens USB pelo driver PKCS#11.", "Tarjetas y tokens USB mediante su driver PKCS#11."),
        ["SimpleSign detects the drivers of the common ICP-Brasil tokens (SafeNet, Watchdata, GD Starsign, Oberthur…) and lists connected tokens and certificates without the PIN. Signing opens a session with the PIN (or the reader's PIN pad). Try it with SoftHSM2 (brew install softhsm / apt install softhsm2) and set SIMPLESIGN_PKCS11_LIBRARY."] = ("O SimpleSign detecta os drivers dos tokens ICP-Brasil comuns (SafeNet, Watchdata, GD Starsign, Oberthur…) e lista tokens conectados e certificados sem o PIN. Assinar abre uma sessão com o PIN (ou o PIN pad da leitora). Teste com o SoftHSM2 (brew install softhsm / apt install softhsm2) e defina SIMPLESIGN_PKCS11_LIBRARY.", "SimpleSign detecta los drivers de los tokens ICP-Brasil comunes (SafeNet, Watchdata, GD Starsign, Oberthur…) y lista tokens conectados y certificados sin el PIN. Firmar abre una sesión con el PIN (o el PIN pad del lector). Pruebe con SoftHSM2 (brew install softhsm / apt install softhsm2) y defina SIMPLESIGN_PKCS11_LIBRARY."),
        ["Cloud certificate (PSC)"] = ("Certificado em nuvem (PSC)", "Certificado en la nube (PSC)"),
        ["ICP-Brasil cloud certificates: BirdID, VIDaaS, NeoID, SafeID, RemoteID…"] = ("Certificados ICP-Brasil em nuvem: BirdID, VIDaaS, NeoID, SafeID, RemoteID…", "Certificados ICP-Brasil en la nube: BirdID, VIDaaS, NeoID, SafeID, RemoteID…"),
        ["OAuth 2.0 with PKCE (the user logs in on the provider's page) or CPF + OTP. The PSC signs hashes with RSA PKCS#1 v1.5. Scopes: single_signature, multi_signature, signature_session."] = ("OAuth 2.0 com PKCE (o usuário faz login na página do provedor) ou CPF + OTP. O PSC assina hashes com RSA PKCS#1 v1.5. Escopos: single_signature, multi_signature, signature_session.", "OAuth 2.0 con PKCE (el usuario inicia sesión en la página del proveedor) o CPF + OTP. El PSC firma hashes con RSA PKCS#1 v1.5. Ámbitos: single_signature, multi_signature, signature_session."),
        ["Cloud Signature Consortium v2"] = ("Cloud Signature Consortium v2", "Cloud Signature Consortium v2"),
        ["Remote signing services that implement the CSC API v2 (QTSPs)."] = ("Serviços de assinatura remota que implementam a API CSC v2 (QTSPs).", "Servicios de firma remota que implementan la API CSC v2 (QTSP)."),
        ["Service authorization (token, client credentials or OAuth), then the credential is authorized per signature: explicit PIN/OTP (credentials/authorize → SAD) or OAuth (credential scope with the hashes). SCAL 2 binds the authorization to the exact hashes."] = ("Autorização do serviço (token, client credentials ou OAuth) e depois a credencial é autorizada por assinatura: PIN/OTP explícito (credentials/authorize → SAD) ou OAuth (escopo credential com os hashes). O SCAL 2 vincula a autorização aos hashes exatos.", "Autorización del servicio (token, client credentials u OAuth) y luego la credencial se autoriza por firma: PIN/OTP explícito (credentials/authorize → SAD) u OAuth (ámbito credential con los hashes). SCAL 2 vincula la autorización a los hashes exactos."),
        ["PAdES baseline"] = ("PAdES baseline", "PAdES baseline"),
        ["The ETSI levels: B-B, B-T, B-LT, B-LTA."] = ("Os níveis ETSI: B-B, B-T, B-LT, B-LTA.", "Los niveles ETSI: B-B, B-T, B-LT, B-LTA."),
        ["The level says what the signature carries so it can be validated later: B-T adds a trusted time, B-LT the validation data, B-LTA a document timestamp that protects all of it."] = ("O nível diz o que a assinatura carrega para ser validada no futuro: B-T acrescenta um tempo confiável, B-LT os dados de validação, B-LTA um carimbo do tempo de documento que protege tudo.", "El nivel indica qué lleva la firma para validarse más adelante: B-T agrega un tiempo confiable, B-LT los datos de validación, B-LTA un sello de tiempo de documento que protege todo."),
        ["ICP-Brasil policy"] = ("Política ICP-Brasil", "Política ICP-Brasil"),
        ["AD-RB, AD-RT, AD-RC or AD-RA: the Brazilian signature policies."] = ("AD-RB, AD-RT, AD-RC ou AD-RA: as políticas de assinatura brasileiras.", "AD-RB, AD-RT, AD-RC o AD-RA: las políticas de firma brasileñas."),
        ["Adds the signature-policy-identifier (OID + hash of the PA), the PBAD.PAdES signature dictionary, and the elements each policy requires. A qualified signature (MP 2.200-2/2001) needs an ICP-Brasil certificate."] = ("Acrescenta o signature-policy-identifier (OID + hash da PA), o dicionário de assinatura PBAD.PAdES e os elementos que cada política exige. Uma assinatura qualificada (MP 2.200-2/2001) precisa de certificado ICP-Brasil.", "Agrega el signature-policy-identifier (OID + hash de la PA), el diccionario de firma PBAD.PAdES y los elementos que exige cada política. Una firma cualificada (MP 2.200-2/2001) necesita un certificado ICP-Brasil."),
        ["Custom signature policy"] = ("Política de assinatura customizada", "Política de firma personalizada"),
        ["A baseline signature with an explicit signature-policy-identifier."] = ("Uma assinatura baseline com signature-policy-identifier explícito.", "Una firma baseline con un signature-policy-identifier explícito."),
        ["For policies other than ICP-Brasil (or to experiment): the OID, the hash algorithm and the hash of the policy document, and optionally its URI (SPuri qualifier)."] = ("Para políticas que não são ICP-Brasil (ou para experimentar): o OID, o algoritmo e o hash do documento da política e, opcionalmente, sua URI (qualificador SPuri).", "Para políticas que no son ICP-Brasil (o para experimentar): el OID, el algoritmo y el hash del documento de la política y, opcionalmente, su URI (calificador SPuri)."),
        ["B-B (basic)"] = ("B-B (básico)", "B-B (básico)"),
        ["Signature with the signing certificate reference. No trusted time."] = ("Assinatura com a referência do certificado do signatário. Sem tempo confiável.", "Firma con la referencia del certificado del firmante. Sin tiempo confiable."),
        ["Valid as long as the certificate is valid and not revoked; after it expires, nothing proves when the signature was made."] = ("Vale enquanto o certificado for válido e não revogado; depois que expira, nada prova quando a assinatura foi feita.", "Es válida mientras el certificado sea válido y no esté revocado; cuando vence, nada prueba cuándo se hizo la firma."),
        ["B-T (timestamp)"] = ("B-T (carimbo do tempo)", "B-T (sello de tiempo)"),
        ["Adds a signature timestamp from a TSA: proof the signature existed at that time."] = ("Acrescenta um carimbo do tempo de uma TSA: prova de que a assinatura existia naquele momento.", "Agrega un sello de tiempo de una TSA: prueba de que la firma existía en ese momento."),
        ["B-LT (long term)"] = ("B-LT (longo prazo)", "B-LT (largo plazo)"),
        ["Adds the certificates and revocation data (CRL/OCSP) in the DSS."] = ("Acrescenta os certificados e os dados de revogação (LCR/OCSP) no DSS.", "Agrega los certificados y los datos de revocación (CRL/OCSP) en el DSS."),
        ["Validators no longer need to fetch revocation data, which may be gone years later."] = ("Os validadores não precisam mais buscar dados de revogação, que podem sumir anos depois.", "Los validadores ya no necesitan buscar datos de revocación, que pueden desaparecer años después."),
        ["B-LTA (archive)"] = ("B-LTA (arquivamento)", "B-LTA (archivo)"),
        ["Adds a document timestamp over everything, renewable before the TSA certificate expires."] = ("Acrescenta um carimbo do tempo de documento sobre tudo, renovável antes do certificado da TSA expirar.", "Agrega un sello de tiempo de documento sobre todo, renovable antes de que venza el certificado de la TSA."),
        ["AD-RB — basic reference"] = ("AD-RB — referência básica", "AD-RB — referencia básica"),
        ["Signature with the policy reference. A timestamp is optional."] = ("Assinatura com a referência da política. O carimbo do tempo é opcional.", "Firma con la referencia de la política. El sello de tiempo es opcional."),
        ["AD-RT — time reference"] = ("AD-RT — referência de tempo", "AD-RT — referencia de tiempo"),
        ["AD-RB plus a signature timestamp from an ICP-Brasil ACT."] = ("AD-RB mais um carimbo do tempo de uma ACT ICP-Brasil.", "AD-RB más un sello de tiempo de una ACT ICP-Brasil."),
        ["AD-RC — complete references"] = ("AD-RC — referências completas", "AD-RC — referencias completas"),
        ["AD-RT plus the validation data in the DSS (Certs, CRLs/OCSPs and a VRI entry) and a later document timestamp (attributes 2.16.76.1.8.2 and .8.3)."] = ("AD-RT mais os dados de validação no DSS (Certs, LCRs/OCSPs e uma entrada VRI) e um carimbo do tempo de documento posterior (atributos 2.16.76.1.8.2 e .8.3).", "AD-RT más los datos de validación en el DSS (Certs, CRLs/OCSPs y una entrada VRI) y un sello de tiempo de documento posterior (atributos 2.16.76.1.8.2 y .8.3)."),
        ["AD-RA — archive"] = ("AD-RA — arquivamento", "AD-RA — archivo"),
        ["AD-RC plus the policy artifacts in the DSS: the PA, the LPA and the LPA signature (PBAD_PolicyArtifacts, PBAD_LpaArtifacts, PBAD_LpaSignatures)."] = ("AD-RC mais os artefatos da política no DSS: a PA, a LPA e a assinatura da LPA (PBAD_PolicyArtifacts, PBAD_LpaArtifacts, PBAD_LpaSignatures).", "AD-RC más los artefactos de la política en el DSS: la PA, la LPA y la firma de la LPA (PBAD_PolicyArtifacts, PBAD_LpaArtifacts, PBAD_LpaSignatures)."),
        ["In Real mode the artifacts are downloaded from the ITI repository and the LPA signature is verified."] = ("No modo Real os artefatos são baixados do repositório do ITI e a assinatura da LPA é verificada.", "En modo Real los artefactos se descargan del repositorio del ITI y se verifica la firma de la LPA."),
        ["Policy version"] = ("Versão da política", "Versión de la política"),
        ["Each policy has versions (v1.1, v1.2…), each with a signing period and accepted roots."] = ("Cada política tem versões (v1.1, v1.2…), cada uma com período de assinatura e raízes aceitas.", "Cada política tiene versiones (v1.1, v1.2…), cada una con un período de firma y raíces aceptadas."),
        ["Automatic picks the newest version in force that accepts the signer's AC Raiz (older PAs only list the roots that existed when they were published). Choose one to pin it; incompatible versions are disabled with the reason."] = ("Automático escolhe a versão vigente mais nova que aceita a AC Raiz do signatário (PAs antigas só listam as raízes que existiam quando foram publicadas). Escolha uma para fixá-la; versões incompatíveis ficam desabilitadas com o motivo.", "Automático elige la versión vigente más nueva que acepta la AC Raíz del firmante (las PA antiguas solo listan las raíces que existían cuando se publicaron). Elija una para fijarla; las versiones incompatibles se desactivan con el motivo."),
        ["Add a timestamp to AD-RB"] = ("Adicionar carimbo do tempo ao AD-RB", "Agregar sello de tiempo a AD-RB"),
        ["The AD-RB PA allows (but does not require) a signature timestamp."] = ("A PA do AD-RB permite (mas não exige) um carimbo do tempo.", "La PA de AD-RB permite (pero no exige) un sello de tiempo."),
        ["Time-stamping authority (TSA)"] = ("Autoridade de carimbo do tempo (TSA)", "Autoridad de sellado de tiempo (TSA)"),
        ["Who signs the trusted time of the signature."] = ("Quem assina o tempo confiável da assinatura.", "Quién firma el tiempo confiable de la firma."),
        ["The library sends the hash of the signature value (RFC 3161) and embeds the token as the signature-time-stamp unsigned attribute. ICP-Brasil requires an accredited ACT for AD-RT and above."] = ("A biblioteca envia o hash do valor da assinatura (RFC 3161) e embute o token como atributo não assinado signature-time-stamp. A ICP-Brasil exige uma ACT credenciada para AD-RT e acima.", "La biblioteca envía el hash del valor de la firma (RFC 3161) e incrusta el token como atributo no firmado signature-time-stamp. ICP-Brasil exige una ACT acreditada para AD-RT y superiores."),
        ["Sandbox TSA"] = ("TSA do sandbox", "TSA del sandbox"),
        ["Offline RFC 3161 TSA signed by the sandbox ACT certificate."] = ("TSA RFC 3161 offline assinada pelo certificado da ACT do sandbox.", "TSA RFC 3161 sin conexión firmada por el certificado de la ACT del sandbox."),
        ["Sandbox TSA (Basic auth)"] = ("TSA do sandbox (autenticação Basic)", "TSA del sandbox (autenticación Basic)"),
        ["Same TSA, but it requires HTTP Basic: user sandbox, password sandbox-tsa. Shows TimestampOptions.Authorization."] = ("A mesma TSA, mas exige HTTP Basic: usuário sandbox, senha sandbox-tsa. Mostra o TimestampOptions.Authorization.", "La misma TSA, pero exige HTTP Basic: usuario sandbox, contraseña sandbox-tsa. Muestra TimestampOptions.Authorization."),
        ["DigiCert"] = ("DigiCert", "DigiCert"),
        ["Free public TSA, trusted by Adobe and most validators."] = ("TSA pública gratuita, confiável para o Adobe e a maioria dos validadores.", "TSA pública gratuita, de confianza para Adobe y la mayoría de los validadores."),
        ["Sectigo"] = ("Sectigo", "Sectigo"),
        ["Free public TSA."] = ("TSA pública gratuita.", "TSA pública gratuita."),
        ["FreeTSA"] = ("FreeTSA", "FreeTSA"),
        ["Free community TSA (freetsa.org)."] = ("TSA comunitária gratuita (freetsa.org).", "TSA comunitaria gratuita (freetsa.org)."),
        ["Custom URL"] = ("URL customizada", "URL personalizada"),
        ["Any http://, https:// or tcp:// (RFC 3161 TCP transport) endpoint, e.g. your ICP-Brasil ACT."] = ("Qualquer endpoint http://, https:// ou tcp:// (transporte TCP do RFC 3161), por exemplo sua ACT ICP-Brasil.", "Cualquier endpoint http://, https:// o tcp:// (transporte TCP de RFC 3161), por ejemplo su ACT ICP-Brasil."),
        ["Authentication"] = ("Autenticação", "Autenticación"),
        ["Many paid TSAs (and ICP-Brasil ACTs) need credentials."] = ("Muitas TSAs pagas (e ACTs ICP-Brasil) exigem credenciais.", "Muchas TSA de pago (y ACT ICP-Brasil) requieren credenciales."),
        ["Basic or Bearer go in an Authorization header; mutual TLS uses a client certificate. Secrets are never written to deferred sessions: resume with WithTimestampOptions."] = ("Basic ou Bearer vão no cabeçalho Authorization; TLS mútuo usa certificado de cliente. Segredos nunca são gravados em sessões adiadas: retome com WithTimestampOptions.", "Basic o Bearer van en el encabezado Authorization; TLS mutuo usa un certificado de cliente. Los secretos nunca se guardan en sesiones diferidas: reanude con WithTimestampOptions."),
        ["The TSA of the document timestamp (B-LTA, AD-RC, AD-RA)."] = ("A TSA do carimbo do tempo de documento (B-LTA, AD-RC, AD-RA).", "La TSA del sello de tiempo de documento (B-LTA, AD-RC, AD-RA)."),
        ["By default the signature TSA (and its credentials) is reused. A separate one can have its own credentials."] = ("Por padrão a TSA da assinatura (e suas credenciais) é reaproveitada. Uma TSA separada pode ter credenciais próprias.", "Por defecto se reutiliza la TSA de la firma (y sus credenciales). Una TSA separada puede tener sus propias credenciales."),
        ["If the TSA or revocation fails"] = ("Se a TSA ou a revogação falhar", "Si la TSA o la revocación fallan"),
        ["Throw (default), or sign at the highest level reached."] = ("Lançar exceção (padrão) ou assinar no maior nível alcançado.", "Lanzar excepción (por defecto) o firmar en el mayor nivel alcanzado."),
        ["With ReturnLowerLevel, SignWithDetailsAsync reports RequestedLevel and AchievedLevel plus warnings, instead of failing the whole operation."] = ("Com ReturnLowerLevel, o SignWithDetailsAsync informa RequestedLevel e AchievedLevel com avisos, em vez de falhar a operação inteira.", "Con ReturnLowerLevel, SignWithDetailsAsync informa RequestedLevel y AchievedLevel con advertencias, en lugar de fallar toda la operación."),
        ["Digest algorithm"] = ("Algoritmo de resumo", "Algoritmo de resumen"),
        ["Hash of the document bytes and of the signed attributes."] = ("Hash dos bytes do documento e dos atributos assinados.", "Hash de los bytes del documento y de los atributos firmados."),
        ["SHA-256 is the default and what ICP-Brasil policies list. SHA-3 needs runtime support (OpenSSL 1.1.1+ or Windows 11)."] = ("SHA-256 é o padrão e o que as políticas ICP-Brasil listam. SHA-3 precisa de suporte do runtime (OpenSSL 1.1.1+ ou Windows 11).", "SHA-256 es el predeterminado y el que listan las políticas ICP-Brasil. SHA-3 necesita soporte del runtime (OpenSSL 1.1.1+ o Windows 11)."),
        ["RSA signature scheme"] = ("Esquema de assinatura RSA", "Esquema de firma RSA"),
        ["PKCS#1 v1.5 (universal) or RSASSA-PSS (probabilistic, recommended for new systems)."] = ("PKCS#1 v1.5 (universal) ou RSASSA-PSS (probabilístico, recomendado para sistemas novos).", "PKCS#1 v1.5 (universal) o RSASSA-PSS (probabilístico, recomendado para sistemas nuevos)."),
        ["PSS uses MGF1 with the same hash and a salt as long as the hash. Not every validator or token supports it."] = ("O PSS usa MGF1 com o mesmo hash e um salt do tamanho do hash. Nem todo validador ou token suporta.", "PSS usa MGF1 con el mismo hash y un salt del tamaño del hash. No todos los validadores o tokens lo admiten."),
        ["Sub-filter"] = ("Sub-filter", "Sub-filter"),
        ["How the PDF signature dictionary identifies the CMS format."] = ("Como o dicionário de assinatura do PDF identifica o formato do CMS.", "Cómo el diccionario de firma del PDF identifica el formato del CMS."),
        ["ETSI.CAdES.detached is PAdES. adbe.pkcs7.detached is the legacy format PDF/A-1 requires (B-B only). PBAD.PAdES (with /Filter /PBAD_PAdES) is what ICP-Brasil policies mandate."] = ("ETSI.CAdES.detached é PAdES. adbe.pkcs7.detached é o formato legado que o PDF/A-1 exige (só B-B). PBAD.PAdES (com /Filter /PBAD_PAdES) é o que as políticas ICP-Brasil exigem.", "ETSI.CAdES.detached es PAdES. adbe.pkcs7.detached es el formato heredado que exige PDF/A-1 (solo B-B). PBAD.PAdES (con /Filter /PBAD_PAdES) es lo que exigen las políticas ICP-Brasil."),
        ["Reserved /Contents size"] = ("Tamanho reservado de /Contents", "Tamaño reservado de /Contents"),
        ["Bytes reserved for the CMS in the PDF (default 16384)."] = ("Bytes reservados para o CMS no PDF (padrão 16384).", "Bytes reservados para el CMS en el PDF (por defecto 16384)."),
        ["B-LT/B-LTA add certificates and CRLs to the DSS (not here), but large chains or timestamps can need more. Too small fails with a clear error."] = ("B-LT/B-LTA acrescentam certificados e LCRs no DSS (não aqui), mas cadeias grandes ou carimbos do tempo podem precisar de mais. Pequeno demais falha com erro claro.", "B-LT/B-LTA agregan certificados y CRLs en el DSS (no aquí), pero cadenas grandes o sellos de tiempo pueden necesitar más. Demasiado pequeño falla con un error claro."),
        ["Preserve PDF/A"] = ("Preservar PDF/A", "Preservar PDF/A"),
        ["Refuse options that would break the document's PDF/A conformance."] = ("Recusar opções que quebrariam a conformidade PDF/A do documento.", "Rechazar opciones que romperían la conformidad PDF/A del documento."),
        ["PDF/A-1 only allows adbe.pkcs7.detached and forbids transparency; PDF/A-2/3 allow PAdES."] = ("O PDF/A-1 só permite adbe.pkcs7.detached e proíbe transparência; PDF/A-2/3 permitem PAdES.", "PDF/A-1 solo permite adbe.pkcs7.detached y prohíbe la transparencia; PDF/A-2/3 permiten PAdES."),
        ["New signature field"] = ("Novo campo de assinatura", "Campo de firma nuevo"),
        ["Adds a field (and its widget) in the new revision."] = ("Acrescenta um campo (e seu widget) na nova revisão.", "Agrega un campo (y su widget) en la nueva revisión."),
        ["Existing empty field"] = ("Campo vazio existente", "Campo vacío existente"),
        ["Signs a field that is already in the document (e.g. prepared by a form)."] = ("Assina um campo que já está no documento (ex.: preparado por um formulário).", "Firma un campo que ya está en el documento (p. ej. preparado por un formulario)."),
        ["The appearance is drawn in the field's own rectangle. The document information dictionary cannot be changed in this mode."] = ("A aparência é desenhada no retângulo do próprio campo. O dicionário de informações do documento não pode ser alterado neste modo.", "La apariencia se dibuja en el rectángulo del propio campo. El diccionario de información del documento no se puede cambiar en este modo."),
        ["Visible stamp"] = ("Carimbo visível", "Sello visible"),
        ["Draws a stamp on the page; invisible signatures only show in the signature panel."] = ("Desenha um carimbo na página; assinaturas invisíveis só aparecem no painel de assinaturas.", "Dibuja un sello en la página; las firmas invisibles solo aparecen en el panel de firmas."),
        ["Text is laid out with Base14 font metrics (shrink-to-fit, wrapping); a QR code and a background image are optional."] = ("O texto é diagramado com as métricas das fontes Base14 (ajuste ao tamanho, quebra de linha); QR code e imagem de fundo são opcionais.", "El texto se compone con las métricas de las fuentes Base14 (ajuste al tamaño, ajuste de línea); el código QR y la imagen de fondo son opcionales."),
        ["QR code"] = ("QR code", "Código QR"),
        ["A QR code with a verification URL."] = ("Um QR code com uma URL de verificação.", "Un código QR con una URL de verificación."),
        ["For VALIDAR (health documents), print your own HTTPS endpoint with ValidarItiQrEndpoint.BuildQrCodeUrl: VALIDAR calls it with _format=application/validador-iti+json and your endpoint answers with ValidarItiQrEndpoint.Respond."] = ("Para o VALIDAR (documentos de saúde), imprima seu próprio endpoint HTTPS com ValidarItiQrEndpoint.BuildQrCodeUrl: o VALIDAR o chama com _format=application/validador-iti+json e seu endpoint responde com ValidarItiQrEndpoint.Respond.", "Para VALIDAR (documentos de salud), imprima su propio endpoint HTTPS con ValidarItiQrEndpoint.BuildQrCodeUrl: VALIDAR lo llama con _format=application/validador-iti+json y su endpoint responde con ValidarItiQrEndpoint.Respond."),
        ["Signature dictionary"] = ("Dicionário de assinatura", "Diccionario de firma"),
        ["Reason, location and contact are written in the PDF signature dictionary."] = ("Motivo, local e contato são gravados no dicionário de assinatura do PDF.", "Motivo, ubicación y contacto se escriben en el diccionario de firma del PDF."),
        ["Viewers show them in the signature panel. They are not part of the CMS."] = ("Os leitores mostram esses dados no painel de assinaturas. Eles não fazem parte do CMS.", "Los visores los muestran en el panel de firmas. No forman parte del CMS."),
        ["Claimed signing time"] = ("Hora de assinatura declarada", "Hora de firma declarada"),
        ["The signing-time the signer claims (not trusted; use a timestamp for proof)."] = ("O signing-time que o signatário declara (não confiável; use carimbo do tempo como prova).", "El signing-time que declara el firmante (no confiable; use un sello de tiempo como prueba)."),
        ["Signer metadata"] = ("Metadados do signatário", "Metadatos del firmante"),
        ["Structured signer data: commitment type, signer id, institution, legal basis…"] = ("Dados estruturados do signatário: tipo de compromisso, id, instituição, base legal…", "Datos estructurados del firmante: tipo de compromiso, id, institución, base legal…"),
        ["Fills the signature dictionary and adds CMS attributes such as commitment-type-indication."] = ("Preenche o dicionário de assinatura e acrescenta atributos CMS como commitment-type-indication.", "Completa el diccionario de firma y agrega atributos CMS como commitment-type-indication."),
        ["Advanced electronic signature (AEA)"] = ("Assinatura eletrônica avançada (AEA)", "Firma electrónica avanzada (AEA)"),
        ["The Lei 14.063/2020 route for signatures without an ICP-Brasil certificate (e.g. Gov.br)."] = ("O caminho da Lei 14.063/2020 para assinaturas sem certificado ICP-Brasil (ex.: Gov.br).", "La vía de la Lei 14.063/2020 para firmas sin certificado ICP-Brasil (p. ej. Gov.br)."),
        ["Adds the commitment, a policy reference and a signer manifest (name, masked CPF, authentication method, IP…) as a signed attribute."] = ("Acrescenta o compromisso, uma referência de política e um manifesto do signatário (nome, CPF mascarado, método de autenticação, IP…) como atributo assinado.", "Agrega el compromiso, una referencia de política y un manifiesto del firmante (nombre, CPF enmascarado, método de autenticación, IP…) como atributo firmado."),
        ["Health document"] = ("Documento de saúde", "Documento de salud"),
        ["Prescriptions, certificates and exam requests (CFM/CFF/CFO…), as VALIDAR expects."] = ("Receitas, atestados e solicitações de exame (CFM/CFF/CFO…), como o VALIDAR espera.", "Recetas, certificados y solicitudes de examen (CFM/CFF/CFO…), como espera VALIDAR."),
        ["Writes the document type and the professional registrations, keyed by OID, to the document information dictionary."] = ("Grava o tipo de documento e os registros profissionais, identificados por OID, no dicionário de informações do documento.", "Escribe el tipo de documento y los registros profesionales, identificados por OID, en el diccionario de información del documento."),
        ["Certify the document"] = ("Certificar o documento", "Certificar el documento"),
        ["A certification (DocMDP) signature: says which later changes are allowed."] = ("Uma assinatura de certificação (DocMDP): diz quais alterações posteriores são permitidas.", "Una firma de certificación (DocMDP): indica qué cambios posteriores se permiten."),
        ["Only the first signature can certify. P=1 forbids any later change (including signatures)."] = ("Só a primeira assinatura pode certificar. P=1 proíbe qualquer alteração posterior (inclusive assinaturas).", "Solo la primera firma puede certificar. P=1 prohíbe cualquier cambio posterior (incluidas las firmas)."),
        ["Document information"] = ("Informações do documento", "Información del documento"),
        ["Entries of the PDF Info dictionary (Title, Author, custom keys), written in the signed revision."] = ("Entradas do dicionário Info do PDF (Title, Author, chaves próprias), gravadas na revisão assinada.", "Entradas del diccionario Info del PDF (Title, Author, claves propias), escritas en la revisión firmada."),
        ["Operation id"] = ("Id da operação", "Id de operación"),
        ["A correlation id for logs and warnings."] = ("Um id de correlação para logs e avisos.", "Un id de correlación para logs y advertencias."),
        ["Sign now"] = ("Assinar agora", "Firmar ahora"),
        ["One call signs the document and reports the achieved level."] = ("Uma chamada assina o documento e informa o nível alcançado.", "Una llamada firma el documento e informa el nivel alcanzado."),
        ["Deferred (two phases)"] = ("Adiado (duas fases)", "Diferido (dos fases)"),
        ["Prepare on the server, sign the signed attributes elsewhere, complete on the server."] = ("Prepara no servidor, assina os atributos assinados em outro lugar, conclui no servidor.", "Prepara en el servidor, firma los atributos firmados en otro lugar, completa en el servidor."),
        ["The pattern for web apps with a local agent, HSMs or cloud keys: the private key never reaches the server. The session is protected by an integrity key and holds no secrets."] = ("O padrão para apps web com agente local, HSMs ou chaves em nuvem: a chave privada nunca chega ao servidor. A sessão é protegida por uma chave de integridade e não guarda segredos.", "El patrón para apps web con agente local, HSM o claves en la nube: la clave privada nunca llega al servidor. La sesión está protegida por una clave de integridad y no guarda secretos."),
        ["Batch"] = ("Lote", "Lote"),
        ["Many documents with one configuration and bounded concurrency."] = ("Muitos documentos com uma configuração e concorrência limitada.", "Muchos documentos con una configuración y concurrencia limitada."),

        // ── Validation ─────────────────────────────────────────────────
        ["The CLI always applies the ICP-Brasil rules and trusts the OS and ICP-Brasil roots; --trust adds roots."] = ("A CLI sempre aplica as regras ICP-Brasil e confia nas raízes do sistema e da ICP-Brasil; --trust acrescenta raízes.", "La CLI siempre aplica las reglas ICP-Brasil y confía en las raíces del sistema y de ICP-Brasil; --trust agrega raíces."),
        ["simplesign inspect signed.pdf shows the structure; simplesign validate-dir validates a folder in bulk."] = ("simplesign inspect signed.pdf mostra a estrutura; simplesign validate-dir valida uma pasta em lote.", "simplesign inspect signed.pdf muestra la estructura; simplesign validate-dir valida una carpeta en lote."),
        ["Valid B-LT (control)"] = ("B-LT válida (controle)", "B-LT válida (control)"),
        ["Signed by the sandbox signer with timestamp and LTV data: every check passes."] = ("Assinada pelo signatário do sandbox com carimbo do tempo e dados LTV: todos os checks passam.", "Firmada por el firmante del sandbox con sello de tiempo y datos LTV: todas las comprobaciones pasan."),
        ["Content changed after signing"] = ("Conteúdo alterado após assinar", "Contenido modificado después de firmar"),
        ["One byte of the signed range (the Author entry) was changed: the ByteRange digest no longer matches."] = ("Um byte da faixa assinada (a entrada Author) foi alterado: o resumo do ByteRange não confere mais.", "Se cambió un byte del rango firmado (la entrada Author): el resumen del ByteRange ya no coincide."),
        ["Signature value changed"] = ("Valor da assinatura alterado", "Valor de la firma modificado"),
        ["One hex digit inside /Contents was changed: the CMS no longer verifies."] = ("Um dígito hexadecimal dentro de /Contents foi alterado: o CMS não confere mais.", "Se cambió un dígito hexadecimal dentro de /Contents: el CMS ya no se verifica."),
        ["Bytes appended after signing"] = ("Bytes acrescentados após assinar", "Bytes agregados después de firmar"),
        ["The file grew after the signature with no new revision: the signature still verifies, and the validator reports that the ByteRange does not cover the whole file."] = ("O arquivo cresceu depois da assinatura sem nova revisão: a assinatura ainda confere, e o validador informa que o ByteRange não cobre o arquivo inteiro.", "El archivo creció después de la firma sin una nueva revisión: la firma sigue verificándose, y el validador informa que el ByteRange no cubre todo el archivo."),
        ["Revoked signer"] = ("Signatário revogado", "Firmante revocado"),
        ["The signer is in the intermediate CA's CRL, fetched by the validator. (The library refuses to build B-LT for a revoked signer.)"] = ("O signatário está na LCR da AC intermediária, buscada pelo validador. (A biblioteca se recusa a montar B-LT para um signatário revogado.)", "El firmante está en la CRL de la AC intermedia, que obtiene el validador. (La biblioteca se niega a construir B-LT para un firmante revocado.)"),
        ["Expired signer"] = ("Signatário expirado", "Firmante vencido"),
        ["Signed while the certificate was valid; it has expired since, and a B-B signature has no timestamp to prove when it was made."] = ("Assinada enquanto o certificado valia; ele já expirou, e uma assinatura B-B não tem carimbo do tempo para provar quando foi feita.", "Firmada mientras el certificado era válido; ya venció, y una firma B-B no tiene sello de tiempo que pruebe cuándo se hizo."),
        ["Root outside the trust anchors"] = ("Raiz fora das âncoras de confiança", "Raíz fuera de los anclajes de confianza"),
        ["Signed with a self-signed certificate that no trusted root vouches for."] = ("Assinada com um certificado autoassinado que nenhuma raiz confiável respalda.", "Firmada con un certificado autofirmado que ninguna raíz de confianza respalda."),
        ["Untrusted TSA"] = ("TSA não confiável", "TSA no confiable"),
        ["The signature timestamp comes from a TSA under an unknown CA. The validator keeps the signature Valid and reports the untrusted TSA chain as a warning."] = ("O carimbo do tempo vem de uma TSA sob uma AC desconhecida. O validador mantém a assinatura Válida e informa a cadeia não confiável da TSA como aviso.", "El sello de tiempo proviene de una TSA bajo una AC desconocida. El validador mantiene la firma Válida e informa la cadena no confiable de la TSA como advertencia."),

        // ── Runner ─────────────────────────────────────────────────────
        ["The options are not compatible; fix the errors listed for each step."] = ("As opções não são compatíveis; corrija os erros listados em cada passo.", "Las opciones no son compatibles; corrija los errores listados en cada paso."),
        ["Every document of the batch failed: {0}"] = ("Todos os documentos do lote falharam: {0}", "Todos los documentos del lote fallaron: {0}"),
        ["Batch: {0} signed, {1} failed, {2:0} ms average per document. The report below validates the first one."] = ("Lote: {0} assinados, {1} com falha, {2:0} ms em média por documento. O relatório abaixo valida o primeiro.", "Lote: {0} firmados, {1} fallidos, {2:0} ms de promedio por documento. El informe de abajo valida el primero."),
        ["Integrity (ByteRange digest)"] = ("Integridade (resumo do ByteRange)", "Integridad (resumen del ByteRange)"),
        ["The signed bytes were not changed after signing."] = ("Os bytes assinados não foram alterados depois da assinatura.", "Los bytes firmados no se modificaron después de firmar."),
        ["The signed bytes were changed after signing: the digest no longer matches."] = ("Os bytes assinados foram alterados depois da assinatura: o resumo não confere mais.", "Los bytes firmados se modificaron después de firmar: el resumen ya no coincide."),
        ["Signature value"] = ("Valor da assinatura", "Valor de la firma"),
        ["Digest {0}."] = ("Resumo {0}.", "Resumen {0}."),
        ["Certificate chain"] = ("Cadeia de certificados", "Cadena de certificados"),
        ["Revocation"] = ("Revogação", "Revocación"),
        ["Signature timestamp"] = ("Carimbo do tempo da assinatura", "Sello de tiempo de la firma"),
        ["TSA trusted."] = ("TSA confiável.", "TSA de confianza."),
        ["TSA not trusted."] = ("TSA não confiável.", "TSA no confiable."),
        ["Choose the signature to co-sign."] = ("Escolha a assinatura a cossinar.", "Elija la firma a cofirmar."),
        ["Choose the signature to countersign."] = ("Escolha a assinatura a contra-assinar.", "Elija la firma a contrafirmar."),
        ["The file is not a CMS SignedData: {0}"] = ("O arquivo não é um CMS SignedData: {0}", "El archivo no es un CMS SignedData: {0}"),
        ["Optional: the content of the detached signature, used only to validate the result. A countersignature signs the other signer's signature value, not the content."] = ("Opcional: o conteúdo da assinatura destacada, usado só para validar o resultado. Uma contra-assinatura assina o valor da assinatura do outro signatário, não o conteúdo.", "Opcional: el contenido de la firma separada, usado solo para validar el resultado. Una contrafirma firma el valor de la firma del otro firmante, no el contenido."),
        ["A countersignature signs the other signer's signature value, not the content."] = ("Uma contra-assinatura assina o valor da assinatura do outro signatário, não o conteúdo.", "Una contrafirma firma el valor de la firma del otro firmante, no el contenido."),
        ["The content is inside the .p7m: CoSign takes it from there."] = ("O conteúdo está dentro do .p7m: o CoSign o pega de lá.", "El contenido está dentro del .p7m: CoSign lo toma de allí."),
        ["The signature is detached: choose the data it signed."] = ("A assinatura é destacada: escolha os dados que ela assinou.", "La firma es separada: elija los datos que firmó."),
        ["Choose the data to sign."] = ("Escolha os dados a assinar.", "Elija los datos a firmar."),
        ["This data is not the content signed by the existing signature (message digest differs): CoSign refuses it."] = ("Estes dados não são o conteúdo assinado pela assinatura existente (o message digest difere): o CoSign os recusa.", "Estos datos no son el contenido firmado por la firma existente (el message digest difiere): CoSign los rechaza."),
        ["This data is not the content signed by the existing signature (message digest differs): the result could not be validated against it. Choose the right data or none."] = ("Estes dados não são o conteúdo assinado pela assinatura existente (o message digest difere): o resultado não poderia ser validado com eles. Escolha os dados certos ou nenhum.", "Estos datos no son el contenido firmado por la firma existente (el message digest difiere): el resultado no podría validarse con ellos. Elija los datos correctos o ninguno."),
        ["A co-signature keeps the existing content type."] = ("Uma cossinatura mantém o tipo de conteúdo existente.", "Una cofirma mantiene el tipo de contenido existente."),
        ["A countersignature lives inside the signer it countersigns: the file keeps the existing content type."] = ("Uma contra-assinatura fica dentro do signatário que ela contra-assina: o arquivo mantém o tipo de conteúdo existente.", "Una contrafirma vive dentro del firmante que contrafirma: el archivo mantiene el tipo de contenido existente."),
        ["Fixed by the existing signature."] = ("Definido pela assinatura existente.", "Definido por la firma existente."),
        ["Signer {0} does not exist: the signature has {1} signer(s)."] = ("O signatário {0} não existe: a assinatura tem {1} signatário(s).", "El firmante {0} no existe: la firma tiene {1} firmante(s)."),
        ["The ICP-Brasil policy sets the level."] = ("A política ICP-Brasil define o nível.", "La política ICP-Brasil define el nivel."),
        ["The policy OID must be dotted digits (e.g. 2.16.76.1.7.1.1.2.3)."] = ("O OID da política deve ter dígitos separados por pontos (ex.: 2.16.76.1.7.1.1.2.3).", "El OID de la política debe tener dígitos separados por puntos (p. ej., 2.16.76.1.7.1.1.2.3)."),
        ["The policy URI must be an absolute URL."] = ("A URI da política deve ser uma URL absoluta.", "La URI de la política debe ser una URL absoluta."),
        ["The ICP-Brasil policy sets the extended form (AD-RV: references, AD-RC: references and values, AD-RA: archive)."] = ("A política ICP-Brasil define a forma estendida (AD-RV: referências, AD-RC: referências e valores, AD-RA: arquivamento).", "La política ICP-Brasil define la forma extendida (AD-RV: referencias, AD-RC: referencias y valores, AD-RA: archivo)."),
        ["Extended forms need a signature timestamp: choose B-T or above."] = ("As formas estendidas precisam de um carimbo do tempo da assinatura: escolha B-T ou acima.", "Las formas extendidas necesitan un sello de tiempo de la firma: elija B-T o superior."),
        ["The countersignature gets its own validation data; the parent signer is left as it was."] = ("A contra-assinatura recebe seus próprios dados de validação; o signatário pai fica como estava.", "La contrafirma recibe sus propios datos de validación; el firmante padre queda como estaba."),
        ["Unknown commitment type."] = ("Tipo de compromisso desconhecido.", "Tipo de compromiso desconocido."),
        ["Fix the issues before signing."] = ("Corrija os problemas antes de assinar.", "Corrija los problemas antes de firmar."),
        ["The signature is detached: choose the data it signed to check its integrity."] = ("A assinatura é destacada: escolha os dados que ela assinou para verificar a integridade.", "La firma es separada: elija los datos que firmó para comprobar su integridad."),
        ["Integrity (message digest)"] = ("Integridade (message digest)", "Integridad (message digest)"),
        ["The signed content matches the message-digest attribute."] = ("O conteúdo assinado confere com o atributo message-digest.", "El contenido firmado coincide con el atributo message-digest."),
        ["The content does not match the message-digest attribute."] = ("O conteúdo não confere com o atributo message-digest.", "El contenido no coincide con el atributo message-digest."),
        ["Validation data (certificate and revocation values)"] = ("Dados de validação (valores de certificados e de revogação)", "Datos de validación (valores de certificados y de revocación)"),
        ["CAdES-C timestamp (escTimeStamp)"] = ("Carimbo CAdES-C (escTimeStamp)", "Sello CAdES-C (escTimeStamp)"),
        ["Archive timestamp"] = ("Carimbo de arquivamento", "Sello de archivo"),
        ["Text contract"] = ("Contrato em texto", "Contrato en texto"),
        ["A short UTF-8 text: any file can be signed in CAdES."] = ("Um texto UTF-8 curto: qualquer arquivo pode ser assinado em CAdES.", "Un texto UTF-8 corto: cualquier archivo puede firmarse en CAdES."),
        ["JSON order"] = ("Pedido em JSON", "Pedido en JSON"),
        ["Structured data, as signed by APIs."] = ("Dados estruturados, como os assinados por APIs.", "Datos estructurados, como los que firman las API."),
        ["PDF as a file"] = ("PDF como arquivo", "PDF como archivo"),
        ["A PDF signed as opaque bytes (CAdES), not inside the PDF (that is PAdES)."] = ("Um PDF assinado como bytes opacos (CAdES), não dentro do PDF (isso é PAdES).", "Un PDF firmado como bytes opacos (CAdES), no dentro del PDF (eso es PAdES)."),
        ["Detached signature (.p7s)"] = ("Assinatura destacada (.p7s)", "Firma separada (.p7s)"),
        ["Maria's signature of the text contract; the content stays outside. Co-sign it (with the same data) or countersign it."] = ("A assinatura de Maria do contrato em texto; o conteúdo fica fora. Cossine-a (com os mesmos dados) ou contra-assine-a.", "La firma de Maria del contrato en texto; el contenido queda fuera. Cofírmela (con los mismos datos) o contrafírmela."),
        ["Enveloped signature (.p7m)"] = ("Assinatura envelopada (.p7m)", "Firma envolvente (.p7m)"),
        ["Maria's signature with the text inside. Co-sign or countersign it without the data."] = ("A assinatura de Maria com o texto dentro. Cossine-a ou contra-assine-a sem os dados.", "La firma de Maria con el texto dentro. Cofírmela o contrafírmela sin los datos."),
        ["Valid detached (control)"] = ("Destacada válida (controle)", "Separada válida (control)"),
        ["The .p7s with its data: every check passes."] = ("O .p7s com seus dados: todas as verificações passam.", "El .p7s con sus datos: todas las comprobaciones pasan."),
        ["Two signers and a countersignature"] = ("Dois signatários e uma contra-assinatura", "Dos firmantes y una contrafirma"),
        ["Maria and João sign the same content (co-signature); Ana countersigns Maria's signature with a timestamp."] = ("Maria e João assinam o mesmo conteúdo (cossinatura); Ana contra-assina a assinatura de Maria com carimbo do tempo.", "Maria y João firman el mismo contenido (cofirma); Ana contrafirma la firma de Maria con sello de tiempo."),
        ["Data changed"] = ("Dados alterados", "Datos modificados"),
        ["The .p7s checked against a copy of the text with one character changed: the message digest no longer matches."] = ("O .p7s verificado contra uma cópia do texto com um caractere alterado: o message digest não confere mais.", "El .p7s comprobado contra una copia del texto con un carácter cambiado: el message digest ya no coincide."),
        ["One byte of the signature value was changed: the RSA verification fails."] = ("Um byte do valor da assinatura foi alterado: a verificação RSA falha.", "Se cambió un byte del valor de la firma: la verificación RSA falla."),
    };
}
